const fs = require('fs');
const repoPath = '/workspaces/IA-MEDIA/IA_PineLine_Assistant';
let projectContext = '';
let systemTemplate = '';
try {
  projectContext = fs.readFileSync(`${repoPath}/PROJECT_CONTEXT.md`, 'utf8');
  systemTemplate = fs.readFileSync(`${repoPath}/SYSTEM_MESSAGE.md`, 'utf8');
} catch (e) {
  // Allow env override for environments where repo isn't mounted
  projectContext = process.env.PROJECT_CONTEXT_CONTENT || '';
  systemTemplate = process.env.SYSTEM_MESSAGE_TEMPLATE || '';
}
return [{ json: { projectContext, systemTemplate, webhook: $input.all()[0] || {} } }];

/* Build markdown progress report from Postgres rows (n8n gives rows in input[0].json) */
const rows = $input.all()[0] && $input.all()[0].json && Array.isArray($input.all()[0].json) ? $input.all()[0].json : [];
let report = '';
if(!rows || rows.length === 0) {
  report = 'No tasks returned from DB. Please verify SQL and credentials.';
} else {
  report = '| id | title | status | assignee | updated_at |\n|---:|---|---|---|---:|\n';
  rows.forEach(r => {
    const id = r.id || '';
    const title = (r.title || r.name || '').toString().replace(/\|/g,'\\|');
    const status = r.status || '';
    const assignee = r.assignee || '';
    const updated = r.updated_at || '';
    report += `| ${id} | ${title} | ${status} | ${assignee} | ${updated} |\n`;
  });
}
return [{ json: { progressReport: report } }];

/* Merge template placeholders and remove Part 3 when no commit info */
const tpl = $input.item.json.systemTemplate || '';
const ctx = $input.item.json.projectContext || '';
const progress = $input.all()[1].json.progressReport || '';
const webhook = $input.item.json.webhook || {};
let out = tpl.replace('{{PROJECT_CONTEXT_CONTENT}}', ctx).replace('{{NOCODB_PROGRESS_REPORT}}', progress);
// Attempt to extract GitHub push commit info if webhook has it
let commitAuthor = '';
let commitMessage = '';
let commitUrl = '';
try {
  const body = webhook[0] && webhook[0].json ? webhook[0].json : webhook;
  if(body && body.commits && body.commits.length) {
    const c = body.commits[0];
    commitAuthor = c.author && c.author.name ? c.author.name : '';
    commitMessage = c.message || '';
    commitUrl = c.url || '';
  }
} catch (e) {}
if(commitAuthor) {
  out = out.replace('{{GITHUB_COMMIT_AUTHOR}}', commitAuthor);
  out = out.replace('{{GITHUB_COMMIT_MESSAGE}}', commitMessage);
  out = out.replace('{{GITHUB_COMMIT_URL}}', commitUrl);
} else {
  // Remove the whole Part 3 block to avoid leaving placeholders
  out = out.replace(/\n### \*\*Part 3[\s\S]*?### \*\*Part 4:/, '\n### **Part 4: User\\'s Action Prompt / Phần 4: Prompt Hành động của Người dùng\n');
}
return [{ json: { finalDoc: out } }];

/* Decide: if Find returned a file -> update node, else create node. This function prepares input for update/create nodes. */
const find = $input.all()[0] && $input.all()[0].json ? $input.all()[0].json : {};
const finalDoc = $input.all().find(i=>i.json && i.json.finalDoc) ? $input.all().find(i=>i.json && i.json.finalDoc).json.finalDoc : (find.finalDoc || '');
let fileId = '';
if(find && find.files && find.files.length) fileId = find.files[0].id;
return [{ json: { fileId, finalDoc } }];
